// One item per page the pull request actually TOUCHED. That is this workflow's whole
// cost profile: CI sends the changed routes, and nothing else is ever captured.
// Screenshotting the entire site on every push is the anti-pattern this template exists
// to avoid — a 40-file PR should cost 2 captures, not 200.
//
// Everything is validated HERE, before the settle wait and before the first capture:
// every URL must carry its https:// scheme. A bare domain comes back from the API as
// HTTP 200 with {error: true, message: 'Url must match format "uri"'} — a soft error on
// the SUCCESS output — so without this check you would burn one API call per page and
// post a comment full of "failed" rows instead of one actionable execution error.
const body = $input.first().json.body || {};

const missing = ['owner', 'repository', 'prNumber'].filter((key) => !body[key]);
if (missing.length) {
  throw new Error(
    `PR preview payload is missing: ${missing.join(', ')}. Expected ` +
      '{"owner":"your-org","repository":"your-repo","prNumber":123,' +
      '"previewUrl":"https://pr-123.preview.example.com",' +
      '"pages":[{"path":"/","label":"Home"}]}.'
  );
}

const hasScheme = (value) => typeof value === 'string' && /^https?:\/\//i.test(value.trim());

const previewUrl = String(body.previewUrl || '').trim();
if (!hasScheme(previewUrl)) {
  throw new Error(
    `"previewUrl" must be a full URL including the scheme (got "${body.previewUrl}"). ` +
      'The Snapshot Site API rejects bare domains with HTTP 200 + ' +
      '{error: true, message: \'Url must match format "uri"\'}.'
  );
}

const pages = body.pages;
if (!Array.isArray(pages) || pages.length === 0) {
  throw new Error(
    'PR preview payload has no "pages" array. Build it from the PR diff ' +
      '(git diff --name-only) and skip the webhook call entirely when the diff touched ' +
      'no pages — that is cheaper than any workflow-side filter.'
  );
}

// A trailing slash on the base plus a leading slash on the path must not produce "//".
const base = previewUrl.replace(/\/+$/, '');
const joinUrl = (rawPath) => {
  const path = String(rawPath === undefined || rawPath === null ? '/' : rawPath).trim();
  if (hasScheme(path)) return path; // CI may send a fully-qualified URL per page
  return `${base}/${path.replace(/^\/+/, '')}`;
};

// A PR touching 40 files usually touches far fewer PAGES: dedupe so the same route is
// never captured twice, and cap the run so a mass rename cannot fire hundreds of calls.
const maxPages = Number(body.maxPages === undefined ? 10 : body.maxPages) || 10;
const seen = new Map();

for (const page of pages) {
  const entry = page || {};
  const rawPath = entry.path;

  if (rawPath !== undefined && rawPath !== null && typeof rawPath !== 'string') {
    throw new Error(`Every "pages[].path" must be a string (got ${typeof rawPath}).`);
  }

  const label = String(entry.label || rawPath || 'page');

  if (typeof rawPath === 'string' && rawPath.includes('://') && !hasScheme(rawPath)) {
    throw new Error(
      `Page "${label}" sent an absolute URL without an https:// scheme ("${rawPath}"). ` +
        'Send a relative path like "/pricing", or a full https:// URL.'
    );
  }

  const url = joinUrl(rawPath);

  if (!hasScheme(url)) {
    throw new Error(
      `Page "${label}" resolved to "${url}", which has no https:// scheme. ` +
        'Check "previewUrl" and "pages[].path" in the CI payload.'
    );
  }

  if (seen.has(url)) continue;
  seen.set(url, {
    label,
    path: typeof rawPath === 'string' && rawPath.length ? rawPath : '/',
    url,
  });
}

const unique = [...seen.values()];
const selected = unique.slice(0, maxPages);
const truncatedCount = unique.length - selected.length;

return selected.map((page, index) => ({
  json: {
    label: page.label,
    path: page.path,
    url: page.url,
    pageNumber: index + 1,
    pageCount: selected.length,
    truncatedCount,
    owner: String(body.owner),
    repository: String(body.repository),
    prNumber: Number(body.prNumber),
    previewUrl: base,
    commit: body.commit ? String(body.commit) : '',
  },
}));

// Runs on the loop's Done branch: N per-page rows in, ONE comment body out.
// One comment per run is deliberate — a 10-page PR must not generate 10 GitHub
// notifications for every reviewer subscribed to the pull request.
const rows = $input.all().map((item) => item.json);
const pr = $('When a Pull Request Preview Is Ready').first().json.body || {};

const owner = String(pr.owner || '');
const repository = String(pr.repository || '');
const prNumber = Number(pr.prNumber);
const previewUrl = String(pr.previewUrl || '').replace(/\/+$/, '');
const commit = pr.commit ? String(pr.commit) : '';

const captured = rows.filter((r) => r.status === 'ok');
const failed = rows.filter((r) => r.status === 'failed');
const truncatedCount = Number(rows.length ? rows[0].truncatedCount : 0) || 0;

// A label containing a pipe would break the markdown table.
const cell = (value) => String(value === undefined || value === null ? '' : value).replace(/\|/g, '\\|');

const lines = [];
lines.push('## Preview screenshots');
lines.push('');
lines.push(
  `**${captured.length} of ${rows.length}** changed page(s) captured from ${previewUrl}` +
    (commit ? ` at \`${commit}\`` : '') +
    '.'
);
lines.push('');

if (captured.length) {
  lines.push('| Page | Path | Size | Preview |');
  lines.push('| --- | --- | --- | --- |');
  for (const row of captured) {
    lines.push(
      `| ${cell(row.label)} | \`${cell(row.path)}\` | ${row.width}x${row.height} | [open](${row.url}) |`
    );
  }
  lines.push('');

  for (const row of captured) {
    lines.push('<details>');
    lines.push(`<summary><strong>${cell(row.label)}</strong> — <code>${cell(row.path)}</code></summary>`);
    lines.push('');
    lines.push(`![${cell(row.label)}](${row.link})`);
    lines.push('');
    lines.push(`[Open ${cell(row.label)} in the preview](${row.url})`);
    lines.push('');
    lines.push('</details>');
    lines.push('');
  }
}

if (failed.length) {
  lines.push('### Could not be captured');
  lines.push('');
  for (const row of failed) {
    lines.push(
      `- \`${cell(row.path)}\` (${cell(row.label)}) — ${cell(row.message) || 'unknown error'} · [open](${row.url})`
    );
  }
  lines.push('');
  lines.push(
    '_An unreachable preview URL is reported here and does not stop the rest of this comment._'
  );
  lines.push('');
}

if (truncatedCount > 0) {
  lines.push(
    `_${truncatedCount} further changed page(s) were not captured (per-run cap). ` +
      'Raise `maxPages` in the CI payload to capture more._'
  );
  lines.push('');
}

lines.push(
  '<sub>Full-page WebP captures at 1280px wide. Only the pages this pull request touched ' +
    'were captured. Posted by an n8n workflow using Snapshot Site.</sub>'
);

return [
  {
    json: {
      commentBody: lines.join('\n'),
      owner,
      repository,
      prNumber,
      capturedCount: captured.length,
      failedCount: failed.length,
      totalCount: rows.length,
      truncatedCount,
      previewUrl,
      commit,
    },
  },
];
